-- v267: good gardens draw wild insects (the farm's Quality, piece 4).
-- Run after v266 and with the matching site code. Safe to run twice.
--
-- The owner's design ("สวนดึงแมลงป่า": a bed with several pollen plants has rare wild insects come to it, for the insect
-- catchers to walk in and catch; a milkweed has monarchs come to it), and his choice of 2026-10-16: haunts of their
-- own, kept few. Each bed of the farm has one haunt, laid after every other (the catalog's insects row: kind 'garden',
-- a turn of half an hour, one in four with an insect, alone as the newcomers' are). While its bed holds at least three
-- living pollen helpers grown to their own picture it draws the uncommon and rare pollinators of the moment, each by
-- its own hours, days, rain and moon but none of its places, weighing what the garden says (`garden.draws`); while a
-- milkweed is grown in it, the monarch too. town.bug_at reads the bed (town.garden_now) only for such a haunt and only
-- in a turn whose roll has an insect, so a page's look at what is out asks little more than it did. Its visitors are
-- not counted with what eats the crops (town.farm_bugs). Scarcity, the net and the catch are as at every haunt.
begin;
set local statement_timeout='30s';
set local lock_timeout='5s';
do $$ begin
 if to_regprocedure('town.quality_care(text,jsonb,jsonb,text,jsonb,text,bigint)') is null or not exists (select 1 from public.town_catalog where key = 'quality' and data ? 'ferts') then raise exception 'Run v266 before v267'; end if;
-- <guards:v267>
 if md5(replace(pg_get_functiondef('town.bug_at(integer,bigint,jsonb,text)'::regprocedure),chr(13),'')) not in ('37b259c5fec9c6f22a6937fbb054229b','37cff6930e3444ac20132c34a2b819a8') then raise exception 'Definition changed: town.bug_at(integer,bigint,jsonb,text); rebuild v267'; end if;
 if md5(replace(pg_get_functiondef('town.farm_bugs(bigint)'::regprocedure),chr(13),'')) not in ('d1e8e1a6d1c2280fb4235e8d8045338a','f67ba3c61cd1bc249cb5e0b2f6dc3156') then raise exception 'Definition changed: town.farm_bugs(bigint); rebuild v267'; end if;
-- </guards:v267>
end $$;

