-- A bed as a good garden sees it (lib/town/garden-visitors' gardenNow): how many living pollen helpers in it are grown
-- to their own picture (stage 4 on: a regrowing one counts), by their roots, against the garden's least; and whether a
-- grown milkweed is among them. Whoever planted them.
create or replace function town.garden_now(p_bed integer, p_now bigint, p_ins jsonb default null)
returns jsonb language plpgsql stable set search_path='' as $$
declare
 n integer:=0; milk boolean:=false; t record; s jsonb; comp jsonb:=town.cat('quality')->'companions';
 least_ integer:=coalesce((coalesce(p_ins,town.cat('insects'))->'garden'->>'least')::integer,3);
begin
 for t in select p.x, p.y, p.soil, p.plant from public.town_plots p
   where p.bed=p_bed and jsonb_typeof(p.plant)='object' and comp->(p.plant->>'crop')->>'role'='pollen'
     and (p.plant->>'root' is null or p.plant->>'root'=p.x::text||','||p.y::text) loop
  s:=town.see(t.x::text||','||t.y::text,jsonb_build_object('soil',t.soil,'plant',t.plant),p_now);
  continue when coalesce((s->>'dead')::boolean,false) or coalesce((s->>'stage')::integer,0)<4;
  n:=n+1;
  if t.plant->>'crop'='milkweed' then milk:=true; end if;
 end loop;
 return jsonb_build_object('good',n>=least_,'milkweed',milk);
end $$;

CREATE OR REPLACE FUNCTION town.bug_at(p_haunt integer, p_now bigint, p_cat jsonb DEFAULT NULL::jsonb, p_word text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
AS $function$
declare
  ins jsonb := coalesce(p_cat, town.cat('insects'));
  h jsonb := ins->'haunts'->p_haunt;
  kind jsonb := ins->'kinds'->(h->>0);
  word text := coalesce(p_word, town.word());
  every bigint;
  phase bigint;
  turn bigint;
  at_ bigint;
  ids jsonb := ins->'order';
  bug jsonb;
  fits boolean[] := '{}';
  total double precision := 0;
  left_ double precision;
  pick text := null;
  i integer;
  lo integer;
  hi integer;
  w double precision;
  -- v264: what a newcomers' haunt has of nothing beside them (its kind's `none`; none at the old ones), and the hour
  none_ double precision := coalesce((kind->>'none')::double precision, 0);
  h_ double precision;
  -- v267: a good garden's haunt, what its bed draws now and what each weighs there (null at every other haunt)
  g jsonb;
  draws jsonb := null;
begin
  if p_haunt is null or p_haunt < 0 or h is null or kind is null then return null; end if;
  every := (kind->>'every')::bigint * 60000;
  phase := floor(town.roll('bugphase', p_haunt) * (kind->>'every')::double precision)::bigint * 60000;
  turn := floor((p_now + phase)::numeric / every)::bigint;
  at_ := turn * every - phase;
  h_ := town.hour_at(at_);
  if town.roll(word || ':bug', p_haunt, turn) >= (kind->>'chance')::double precision then return null; end if;
  -- v267: a good garden's haunt (lib/town/insects' GOOD_GARDEN): its bed as it is now (the bed its first perch stands
  -- in), the uncommon and rare pollinators while it is good and the monarch while a milkweed is grown in it, each by its
  -- hours, days, rain and moon but none of its places, weighing what the garden says; nothing while it draws nothing
  if h->>0 = 'garden' then
    g := town.garden_now(town.bed_of(floor((h->3->0->>0)::numeric)::integer, floor((h->3->0->>1)::numeric)::integer), p_now, ins);
    draws := case when (g->>'good')::boolean then coalesce(ins->'garden'->'draws', '{}'::jsonb) else '{}'::jsonb end
      || case when (g->>'milkweed')::boolean then jsonb_build_object(ins->'garden'->'milkweed'->>0, (ins->'garden'->'milkweed'->>1)::double precision) else '{}'::jsonb end;
    if draws = '{}'::jsonb then return null; end if;
  end if;
  for i in 0..jsonb_array_length(ids) - 1 loop
    bug := ins->'bugs'->(ids->>i);
    fits := fits || (case when draws is not null then draws ? (ids->>i) and town.wild_fits(bug - 'places' - 'zones', ids->>i, h->>1, h->>2, at_, word)
      else bug->'at' ? (h->>0) and town.wild_fits(bug, ids->>i, h->>1, h->>2, at_, word) end);
    if fits[i + 1] then total := total + case when draws is not null then (draws->>(ids->>i))::double precision else town.bug_weight(bug, h_, ins) end; end if;
  end loop;
  left_ := town.roll(word || ':which', p_haunt, turn) * (total + none_);
  for i in 0..jsonb_array_length(ids) - 1 loop
    if fits[i + 1] then
      pick := ids->>i;
      left_ := left_ - case when draws is not null then (draws->>pick)::double precision else town.bug_weight(ins->'bugs'->pick, h_, ins) end;
      exit when left_ < 0;
    end if;
  end loop;
  if pick is null or (none_ > 0 and left_ >= 0) then return null; end if;
  -- hunted, it is out less often (lib/town/insects.ts's plentyOf): where the number fell within the insect's own
  -- share of the weights, against how much of itself its kind is as the turn begins. Nothing takes its place.
  w := case when draws is not null then (draws->>pick)::double precision else town.bug_weight(ins->'bugs'->pick, h_, ins) end;
  if (case when left_ < 0 then (left_ + w) / w else 0 end) >= town.plenty(pick, at_, ins) then return null; end if;
  lo := (ins->'bugs'->pick->'n'->>0)::int;
  hi := (ins->'bugs'->pick->'n'->>1)::int;
  return jsonb_build_object('turn', turn, 'bug', pick, 'n', lo + floor(town.roll(word || ':bugs', p_haunt, turn) * (hi - lo + 1))::int,
    'seed', p_haunt::bigint * 100003 + turn, 'until', (turn + 1) * every - phase);
end;
$function$;

CREATE OR REPLACE FUNCTION town.farm_bugs(p_now bigint)
 RETURNS integer
 LANGUAGE plpgsql
 STABLE
AS $function$
declare
  ins jsonb := town.cat('insects');
  word text := town.word();
  backs jsonb := town.backs_now(p_now);
  rids jsonb := coalesce(town.cat('farming')->'rids', '{}'::jsonb);
  has jsonb;
  taken integer;
  n integer := 0;
  i integer;
begin
  for i in 0..jsonb_array_length(ins->'haunts') - 1 loop
    continue when ins->'haunts'->i->>1 <> 'farm';
    -- v267: a good garden's visitors come for its flowers, and are not counted with what eats the crops
    continue when ins->'haunts'->i->>0 = 'garden';
    has := town.bug_here(i, p_now, backs, ins, word);
    continue when has is null or rids ? (has->>'bug') or town.cat('insect_garden')->'visitors' ? (has->>'bug');
    select count(*)::int into taken from public.town_takes tk where tk.what = 'haunt' and tk.place = i and tk.turn = (has->>'turn')::bigint;
    continue when taken >= (ins->'kinds'->(ins->'haunts'->i->>0)->>'shares')::int;
    n := n + 1;
  end loop;
  return n;
end;
$function$;

revoke all on function town.garden_now(integer,bigint,jsonb) from public, anon, authenticated;
-- (the functions written over keep the grants they had)

commit;
notify pgrst, 'reload schema';

